        padding-inline: var(--comment-padding-inline);

        .comments--system-expanded .comment-by-system & {
          --stripe-color: color-mix(in srgb, var(--card-color) 10%, var(--color-canvas));
        }
      }

      .reactions {
        display: none !important;
